import {termPrincipal} from './term-deposit.js';
import {renderTermDeposits} from './term-deposit-ui.js';
import {renderProtection} from './deposit-protection.js';
import {renderInterestTax} from './interest-tax-ui.js';
import {gameEconomy} from './engine.js';
import {canUpgradeHistory,LATEST_HISTORY_EDITION} from './history-upgrade.js';
import {renderObservedMacro} from './observed-macro.js';
import {renderHousehold} from './household-ui.js';
import {renderRiskCoverage} from './risk-statistics.js';
import {loanLiability,livingShortfall,loanDue,quoteLoan} from './credit.js';
import {salaryIncome,businessValue,age,expenses,income,worth,availableActions} from './engine.js';
import {fortune,satisfaction} from './life-risk.js';

export const earnedIncome=s=>Math.max(0,salaryIncome(s)+businessValue(s));
export function renderLiving(s,{escape:e,won}){const options=availableActions(s).filter(a=>['job','business','simple','leisure'].includes(a.id));return `<section class="finance-heading"><span class="eyebrow">MY EVERYDAY</span><h2>내가 선택하는 생활</h2><p>일·가게·생활비를 조정하거나 갖고 싶던 생활을 고릅니다.</p></section><div class="finance-account-grid"><article class="finance-box"><span>근로·사업 소득</span><strong>${won(earnedIncome(s))}</strong></article><article class="finance-box"><span>생활·주거비</span><strong>${won(expenses(s))}</strong></article></div>${renderHousehold(s,{won,escape:e})}<div class="living-actions">${options.map(a=>`<button class="finance-command" data-action="${a.id}" ${a.disabled?'disabled':''}><b>${e(a.title)}</b><span>${e(a.detail)}</span></button>`).join('')}</div><div class="record-links"><button class="btn secondary" data-tab="shop" ${age(s)<19?'disabled':''}>집·차·취향 고르기</button><button class="btn secondary" data-tab="world" ${age(s)<19?'disabled':''}>나의 공간·가족·취미</button></div><details class="finance-help"><summary>운세·굿 · 마음 다잡기</summary><p>운 체감 ${s.rules?.luckFeeling||0}/10 · 만족감에만 영향을 주는 선택입니다. 사건 확률과 시장은 변하지 않습니다. 비용은 실제 서비스 가격이 아닌 게임 가정입니다.</p><div class="record-links">${[['reading','운세 이야기 · 30,000원'],['ritual','굿 · 500,000원']].map(([id,title])=>`<button class="btn secondary small" data-comfort-open="${id}" ${!s.rules||s.pending||s.ended||age(s)<19||s.rules.comfortMonth===s.month?'disabled':''}>${title}</button>`).join('')}</div></details><details class="finance-help"><summary>전체 생활 장부와 기존 관리 기능</summary><button class="btn secondary small" data-tab="assets">상세 관리 열기 →</button></details>`;}
export function renderFinance(s,{escape:e,won,date}){
 const contracts=s.credit?.contracts||[],active=contracts.filter(c=>c.balance+c.arrearsInterest>0),quote=quoteLoan(s,1000000,36,earnedIncome(s));
 return `<section class="finance-heading"><span class="eyebrow">MONEY, ONE DECISION AT A TIME</span><h2>내 돈의 다음 움직임</h2><p>필요한 거래를 고른 뒤 금액과 결과를 확인합니다.</p></section><div class="finance-command-grid">${[['buy','자산 매수','주식·달러·금'],['sell','자산 매도','보유 자산을 현금으로']].map(([side,title,detail])=>`<button class="finance-command" data-quick-trade="${side}" ${s.ended||age(s)<19||!s.market?'disabled':''}><b>${title}</b><span>${detail}</span></button>`).join('')}<button class="finance-command" data-reserve-open="deposit" ${s.ended||age(s)<19?'disabled':''}><b>예금잔액에 넣기</b><span>금액을 직접 입력</span></button><button class="finance-command" data-reserve-open="withdraw" ${s.ended||age(s)<19||s.deposit<=0?'disabled':''}><b>예금잔액에서 꺼내기</b><span>보유 잔액 안에서 인출</span></button></div><details class="finance-help"><summary>현재 예금 기능과 실제 상품의 차이</summary><p>현재 잔액은 기존 게임의 변동금리 예금 모형입니다. 실제 당시 정기예금의 판매 조건·만기·중도해지 자료는 아직 연결하지 않았습니다. 금액 버튼을 실제 상품의 최소·최대 가입금액으로 주장하지 않습니다.</p></details><div class="finance-account-grid"><article class="finance-box"><span>사용 가능한 현금</span><strong>${won(s.cash)}</strong></article><article class="finance-box"><span>예금잔액 · 현재 모형</span><strong>${won(s.deposit)}</strong></article><article class="finance-box"><span>대출 모형 · 기존 가정 부채 포함</span><strong>${won(loanLiability(s))}</strong></article><article class="finance-box"><span>은행대출과 별도인 생활비 부족분</span><strong>${won(livingShortfall(s))}</strong></article></div>${renderInterestTax(s,Math.round(s.deposit*gameEconomy(s).deposit/12),{won,escape:e})}${renderProtection(s,{won})}${renderTermDeposits(s,{won,escape:e,date})}<section class="credit-section"><div class="section-heading"><div><span class="eyebrow">CONTRACTS / REPAYMENT</span><h3>대출과 상환</h3></div><button class="btn small" data-credit-open="borrow" ${s.ended||age(s)<19?'disabled':''}>대출 조건 확인</button></div><div class="credit-summary"><span>다음 월 예정 원리금 <b>${won(loanDue(s))}</b></span><span>진행 중 계약 <b>${active.length}건</b></span></div><p class="note">대출금은 현금과 부채를 동시에 늘립니다. 생활비 부족분을 자동으로 은행대출로 바꾸지 않습니다.</p><div class="credit-contracts">${contracts.map(c=>`<article class="credit-contract"><div><span class="mini-label">${e(c.id)} · ${c.balance+c.arrearsInterest===0?'완납':'계약 확정'}</span><h4>${date(c.month)} · ${c.term}개월 원금균등</h4></div><dl><div><dt>남은 원금</dt><dd>${won(c.balance)}</dd></div><div><dt>고정 연 금리</dt><dd>${(c.rate*100).toFixed(2)}%</dd></div><div><dt>미납 원금</dt><dd>${won(c.arrearsPrincipal)}</dd></div><div><dt>미납 이자</dt><dd>${won(c.arrearsInterest)}</dd></div></dl><button class="btn secondary small" data-credit-repay="${e(c.id)}" ${s.ended||c.balance+c.arrearsInterest<=0?'disabled':''}>추가 상환 확인</button></article>`).join('')||'<p class="empty-finance">아직 계약한 대출이 없습니다. 조건을 확인해도 확정 전에는 돈과 부채가 바뀌지 않습니다.</p>'}</div>${livingShortfall(s)>0?`<button class="btn secondary small" data-shortfall-open="yes" ${s.ended||s.cash<=0?'disabled':''}>생활비 부족분 직접 상환</button>`:''}<details class="finance-help"><summary>대출 조건의 출처와 미반영 범위</summary><p>원금균등은 원금을 나누어 갚고 남은 원금에 이자를 계산하는 방식입니다. <a href="https://obank.kbstar.com/products/kb-soho-credit-loan-transfer.html" target="_blank" rel="noopener noreferrer">은행의 상환 방식 설명 ↗</a></p><p>현재 제공하는 계약은 실제 당시 은행상품이 아닌 사용자가 확인 후 선택하는 교육용 신용대출입니다. 연 금리는 모형 예금금리 +4%p, 3~15% 범위로 고정합니다. 한도는 연 근로·사업 소득의 80% 이내, 최대 1억원이며 첫 달 원리금은 월 해당 소득의 30% 안에서 심사합니다. 이는 실제 DSR·신용평점·은행 승인 기준이 아닙니다.</p><p>월 단위 이자, 원금균등, 12·24·36·60개월, 월 1건·진행 3건의 게임 규칙입니다. 연체금리는 가산하지 않고 미납 이자를 별도 부채로 기록합니다. 중도상환수수료·일별 이자·기한이익 상실·담보·실제 세금과 법정 규제는 미반영입니다. 금리·기간은 확정 후 수정하지 않습니다.</p></details></section><details class="finance-help"><summary>시장·가격·보유 자산을 자세히 보기</summary><button class="btn secondary small" data-tab="market">상세 시장 화면 열기 →</button></details>`;
}
export function renderRecords(s,{escape:e,won,date}){const f=fortune(s);return `<section class="finance-heading"><span class="eyebrow">MY RECORD</span><h2>선택이 쌓여, 나의 삶이 되었다.</h2></section><div class="record-stats"><span>삶 만족도 <b>${satisfaction(s)}</b></span><span>겪은 우연 <b>${f.grade}</b></span><span>확정한 선택 <b>${s.rules?.confirmed.length||s.log.filter(x=>x.type==='choice').length}개</b></span></div><p class="note">총운은 우연한 사건의 발생을 요약한 게임 등급입니다. 능력·투자 실력·미래의 사고 확률이 아니며 의식이나 소비로 바뀌지 않습니다.</p><div class="achievement-list">${s.rules?.achievements.map(a=>`<span>✓ ${e(a.title)} <small>${date(a.month)}</small></span>`).join('')||'<p>안전망 마련·대출 완납·위기 이후 회복·송금 전 검증의 기록이 이곳에 쌓입니다.</p>'}</div><div class="record-links"><button class="btn secondary small" data-tab="notebook">경제 개념 수첩</button><button class="btn secondary small" data-tab="journal">전체 장부</button><button class="btn small" data-ui="receipt">삶의 영수증 내려받기</button><button class="text-button" data-ui="export">저장 JSON 백업 ↗</button></div>${s.historyEdition?renderObservedMacro(s,{won,escape:e},worth(s)):''}${s.learning&&s.market?`<details class="finance-help"><summary>역사 자료 · ${s.historyEdition||0}판 / 최신 ${LATEST_HISTORY_EDITION}판</summary><p>새 사건은 이후 진행하는 달부터 연결됩니다. 지나간 사건·자산·확정 선택은 소급하지 않습니다.</p>${(s.historyEdition||0)<LATEST_HISTORY_EDITION?`<button class="btn secondary small" data-history-upgrade="yes" ${canUpgradeHistory(s)?'':'disabled'}>새 역사 자료 연결</button>${s.pending?'<p class="note">현재 선택을 먼저 마쳐 주세요.</p>':''}`:'<p>최신 자료를 사용하고 있습니다.</p>'}</details>`:''}${renderRiskCoverage(e,s)}<details class="receipt-preview" ${s.ended?'open':''}><summary>${s.ended?'마지막 삶의 영수증':'지금까지의 삶의 영수증'}</summary>${receiptBody(s,{escape:e,won,date})}</details>`;}
export function receiptBody(s,{escape:e,won,date}){const f=fortune(s);return `<article class="life-receipt"><header><span>IF WORLD / LIFE RECEIPT</span><h3>${e(s.name)}의 삶</h3><p>${date(s.startDate||s.start)} → ${date(s.month)}<br>${s.ended?'생애 종료':'진행 중 기록'} · ${s.rules?.difficulty==='hard'?'어려움':'보통'}</p></header><dl><div><dt>현재 나이</dt><dd>${age(s)}세</dd></div><div><dt>순자산</dt><dd>${won(worth(s))}</dd></div>${s.termDeposits?`<div><dt>계약 예금 원금 · 미지급 이자 제외</dt><dd>${won(termPrincipal(s))}</dd></div>`:''}<div><dt>총부채</dt><dd>${won(s.debt)}</dd></div><div><dt>삶 만족도</dt><dd>${satisfaction(s)}</dd></div><div><dt>겪은 우연</dt><dd>${f.grade} · ${f.count}건</dd></div><div><dt>읽은 역사 장면</dt><dd>${s.learning?.entries.length||0}개</dd></div></dl><div class="receipt-lines">${s.log.filter(x=>x.type!=='month').map(x=>`<section><time>${date(x.month)}</time><b>${e(x.title)}</b><p>${e(x.text)}</p></section>`).join('')}</div><footer>같은 역사 속에서 선택한 한 사람의 기록.<br>금융 가격·대출 조건·생활 사건 확률은 모형이며 실제 과거 경제 전체를 재현하지 않습니다.</footer></article>`;}
export function receiptDocument(s,ctx){return `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IF 세계 · 삶의 영수증</title><style>body{font:14px/1.8 sans-serif;color:#263b54;background:#f2f5f8;padding:24px}.life-receipt{max-width:620px;margin:auto;background:white;padding:32px;border-top:6px solid #218aff}.life-receipt header,.life-receipt footer{text-align:center}h3{font-size:26px}dl>div{display:flex;justify-content:space-between;gap:24px;padding:9px 0;border-bottom:1px dashed #d2dbe4}dd{margin:0;text-align:right}.receipt-lines section{border-top:1px dashed #aabccb;padding:20px 0}.receipt-lines time{display:block;font-size:12px;color:#607386}.receipt-lines b{display:block;margin:5px 0}.receipt-lines p{font-size:13px;overflow-wrap:anywhere}.life-receipt footer{border-top:1px dashed #aabccb;padding-top:24px;font-size:12px}@media print{body{padding:0;background:white}.life-receipt{max-width:none;padding:0}section{break-inside:avoid}}</style><body>${receiptBody(s,ctx)}</body></html>`;}
